SELECT count(*) AS nrow, min(rowid) AS min_rowid, max(rowid) AS max_rowid, sum(a IS NOT NULL OR b IS NOT NULL OR c IS NOT NULL OR d IS NOT NULL OR e IS NOT NULL OR f IS NOT NULL OR g IS NOT NULL OR h IS NOT NULL OR i IS NOT NULL OR j IS NOT NULL OR k IS NOT NULL OR l IS NOT NULL OR m IS NOT NULL OR n IS NOT NULL OR o IS NOT NULL OR p IS NOT NULL OR q IS NOT NULL OR r IS NOT NULL OR s IS NOT NULL OR t IS NOT NULL) AS nonnull_rows, (SELECT sql FROM sqlite_schema WHERE type='index' AND name='i2') AS i2_sql, (SELECT group_concat(tbl || ':' || ifnull(idx,'') || ':' || stat, '|') FROM (SELECT tbl, idx, stat FROM sqlite_stat1 ORDER BY tbl, idx)) AS statistics FROM t1;